const products=[{id:1,name:'Camiseta Essencial Off-white',brand:'Órbita',category:'Camisetas',price:89.9,image:'tee',tag:'ESSENCIAL',description:'Uma base para todas as suas combinações. Camiseta conceito em tom off-white, com proposta de modelagem confortável.'},{id:2,name:'Moletom Everyday',brand:'Órbita',category:'Moletons',price:189.9,image:'hoodie',tag:'SUA NOVA VIBE',description:'Para levar seu estilo aos dias mais frescos. Moletom conceito com capuz e proposta de modelagem descontraída.'},{id:3,name:'Mochila Caminhos',brand:'Forma Livre',category:'Acessórios',price:129.9,image:'bag',tag:'PRA IR JUNTO',description:'Um acessório para acompanhar novas ideias e caminhos. Modelo ilustrativo para explorar a vitrine.'},{id:4,name:'Coleção Dias Leves',brand:'Terra Leve',category:'Camisetas',price:99.9,image:'fashion',tag:'FEITO PRA VOCÊ',description:'Inspiração para uma coleção que combina com seus dias. Imagem editorial ilustrativa; este produto é uma demonstração.'}];
const $=s=>document.querySelector(s),money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('O armazenamento do navegador está indisponível.')}}
let favorites=read('camizetas-favorites',[]),bag=read('camizetas-bag',[]),category='Todos',brand='',size='M';
if(!Array.isArray(favorites))favorites=[];if(!Array.isArray(bag))bag=[];bag=bag.filter(i=>products.some(p=>p.id===i.id)&&typeof i.size==='string');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function render(){const q=$('#search').value.toLocaleLowerCase('pt-BR');const list=products.filter(p=>(category==='Todos'||category==='Favoritos'&&favorites.includes(p.id)||category===p.category)&&(!brand||brand===p.brand)&&`${p.name} ${p.brand}`.toLocaleLowerCase('pt-BR').includes(q));$('#products').innerHTML=list.map(p=>`<article class="product"><button class="favorite ${favorites.includes(p.id)?'selected':''}" data-favorite="${p.id}" aria-label="${favorites.includes(p.id)?'Remover dos':'Adicionar aos'} favoritos: ${p.name}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button><button class="product-image" data-product="${p.id}" aria-label="Ver ${p.name}"><img src="assets/${p.image}.jpg" alt="${p.name} — imagem ilustrativa" loading="lazy"><span class="product-tag">${p.tag}</span></button><p class="product-brand">${p.brand} ↗</p><button class="product-title" data-product="${p.id}">${p.name}</button><p class="product-price">${money(p.price)}</p><p class="product-sub">Produto demonstrativo</p></article>`).join('');$('#empty').hidden=list.length>0;$('#bag-count').textContent=String(bag.length)}
$('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;brand='';$('.filters .active')?.classList.remove('active');b.classList.add('active');render()});$('#search').addEventListener('input',render);
$('#products').addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){const id=+f.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(n=>n!==id):[...favorites,id];save('camizetas-favorites',favorites);render();return}const b=e.target.closest('[data-product]');if(b)openProduct(+b.dataset.product)});
function openProduct(id){const p=products.find(p=>p.id===id);size=p.category==='Acessórios'?'Único':'M';$('#product-detail').innerHTML=`<img class="detail-image" src="assets/${p.image}.jpg" alt="${p.name}"><p class="product-brand">${p.brand} · Vitrine conceito</p><h2>${p.name}</h2><p class="dialog-intro">${p.description}</p><p class="detail-price">${money(p.price)}</p><p class="eyebrow">TAMANHO</p><div class="sizes">${(p.category==='Acessórios'?['Único']:['P','M','G','GG']).map(s=>`<button class="${size===s?'active':''}" data-size="${s}" aria-pressed="${size===s}">${s}</button>`).join('')}</div><button class="button" id="add-to-bag">Adicionar à sacola ↗</button><p class="product-sub">Simulação · sem compra ou cobrança.</p>`;$('#product-dialog').showModal();$('#add-to-bag').onclick=()=>{bag.push({id,size});save('camizetas-bag',bag);render();$('#product-dialog').close();toast('Adicionado à sacola de demonstração.')};$('.sizes').onclick=e=>{if(!e.target.dataset.size)return;size=e.target.dataset.size;document.querySelectorAll('[data-size]').forEach(b=>{b.classList.toggle('active',b.dataset.size===size);b.setAttribute('aria-pressed',b.dataset.size===size)})}}
document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>{brand=b.dataset.brand;category='Todos';$('#search').value='';document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category==='Todos'));render();$('#explorar').scrollIntoView({behavior:'smooth'});toast(`Mostrando a loja conceito ${brand}`)});
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function renderBag(){$('#bag-items').innerHTML=bag.length?bag.map((i,index)=>{const p=products.find(p=>p.id===i.id);return `<div class="bag-row"><img src="assets/${p.image}.jpg" alt=""><div><p>${p.name}</p><small>${p.brand} · Tamanho ${safe(i.size)}</small><p>${money(p.price)}</p></div><button class="remove" data-remove="${index}">Remover</button></div>`}).join(''):'<p class="dialog-intro">Sua sacola está esperando os seus favoritos.</p>';$('#bag-total').textContent=bag.length?'Total demonstrativo: '+money(bag.reduce((sum,i)=>sum+products.find(p=>p.id===i.id).price,0)):'';$('#bag-count').textContent=String(bag.length)}
$('.bag').onclick=()=>{renderBag();$('#bag-dialog').showModal()};$('#bag-items').onclick=e=>{if(e.target.dataset.remove===undefined)return;bag.splice(+e.target.dataset.remove,1);save('camizetas-bag',bag);renderBag()};$('#continue-shopping').onclick=()=>{$('#bag-dialog').close();$('#explorar').scrollIntoView({behavior:'smooth'})};
render();
